with d as (select value r from jsonb_array_elements($q$[{"notes":["Make the cashew cream up to 2 days ahead and keep in the fridge; assemble with herbs and walnuts just before serving.","If you don't have raw cashews, use store-bought cashew butter (about 150 g) and skip the soaking step. You'll need a bit less water, start with 60 ml.","Traditionally made with yoghurt; this version is just as creamy, and Layla's family has eaten it both ways for years."],"id":"a0004fab-cb3d-49cf-b578-b9ddd7d3b26e"},{"notes":["Keeps in the fridge for three days. Reheat gently in a pot over low heat, or microwave in a covered bowl.","Make it a day ahead: the flavour deepens overnight.","Freeze the cooled braised ribs in the sauce for up to three months.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"steps":[{"text":"Blanch the short ribs: bring a large pot of water to the boil, add the ribs and boil for 3 minutes. Drain and rinse the ribs under cold running water, scrubbing gently to remove any scum. Pat dry."},{"text":"Heat a heavy-based braising pot or large Dutch oven over medium-high heat. Add 1 tbsp of the sesame oil. Working in batches, brown the ribs on all sides, about 10 minutes total. Transfer to a plate."},{"text":"Return the pot to medium heat and add the remaining sesame oil. Add the garlic and ginger, stirring for 30 seconds until fragrant."},{"text":"Return the ribs to the pot. Add the soy sauce, water, honey, spring onions, drained shiitake mushrooms (reserving the soaking liquid) and jujubes. Pour in 100 ml of the mushroom soaking liquid. Bring to a boil, then reduce heat to low, cover, and simmer gently for 1.5 to 2 hours, until the ribs are completely tender and the meat pulls easily from the bone."},{"text":"Remove the pot from the heat. Discard the spring onions, garlic and ginger pieces (or leave them in if you prefer). Taste and season with salt if needed, the soy sauce will likely be salty enough."},{"text":"Serve the short ribs hot in shallow bowls with the braising liquid spooned over. Scatter with toasted sesame seeds. Serve with steamed white rice and kimchi on the side."}],"id":"7b7aa56b-bee1-43c3-9905-b5c45692cd6b"},{"notes":["Kuah lkor is gentler than laksa, if you like more heat, add a sliced green chilli or two to the paste.","The tamarind paste keeps the broth light and stops it feeling too rich; don't skip it.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"30052fa8-fae6-4c6e-8d25-13ee92d39b63"},{"steps":[{"text":"Toast the sesame seeds in a heavy-bottomed pan over medium heat, stirring constantly, until fragrant and lightly golden, about 5 minutes. Tip onto a plate."},{"text":"Pour the honey into the same pan over medium heat. Warm, swirling gently, until it turns a deep amber, about 8 minutes. Don't stir it, just let it happen. You'll know it's ready when it smells toasted and a drop in cold water snaps cleanly."},{"text":"Remove from heat. Working fast, add the vanilla and salt, then tip in the toasted sesame seeds. Stir hard until everything is coated."},{"text":"Pour onto a baking tray lined with baking paper, spreading it thin and even with an oiled spatula. Work quickly, it sets fast."},{"text":"Cool completely at room temperature, about 2 hours. Break into pieces with your hands. That's it, mate."}],"id":"450c022b-b790-49df-9243-574ab5f4cf92"},{"notes":["Fresh fish cakes are best if you can find them at an Asian grocer. Canned work fine too, just drain them well.","The shrimp paste makes this dish. It's pungent and funky on its own, but dissolves into the broth and gives it depth.","If you can't find fresh Vietnamese mint, use extra Thai basil or regular mint, it won't be the same, but it still works."],"steps":[{"text":"In a small bowl, mash the shrimp paste with a fork until it breaks down. Add 2 tbsp of hot water and stir well until it dissolves into a pungent liquid; set aside."},{"text":"Heat 1 tbsp oil in a large pot over medium heat. Add the minced garlic and sliced chillies, stirring constantly until fragrant, about 1 minute."},{"text":"Add the shrimp paste liquid to the pot and stir for another minute, until fragrant, letting the flavour bloom. Pour in the stock and bring to a simmer until bubbling gently."},{"text":"Add the fish sauce and caster sugar, stirring to dissolve. Taste and adjust, it should be salty, pungent, and slightly sweet. This is Huế food; don't be timid."},{"text":"Gently slide the fish cake slices into the simmering broth and cook for 5 to 8 minutes until they're heated through and tender."},{"text":"While the broth cooks, divide the cooked rice vermicelli between four bowls."},{"text":"Ladle the hot broth and fish cakes over the noodles. Top with fresh Vietnamese mint, coriander, and spring onion. Serve with lime wedges and extra chillies on the side for those who want more heat."}],"id":"461116e3-cd67-4ab5-b854-7d174e0232c3"},{"notes":["Serve with white rice and farofa (toasted cassava flour) on the side to soak up the sauce.","Any firm white fish works, barramundi, snapper, ling or flathead are all good choices. Avoid delicate fish like flake.","Make ahead: prep the vegetables and fish the day before; cook just before serving so the fish stays tender.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the dendê oil in a large, heavy-bottomed pot over medium-high heat. Add the onion and capsicum, stirring occasionally, until softened and the onion is starting to caramelize, about 8 minutes."},{"text":"Add the garlic and chilli, stirring constantly for 1 minute until fragrant."},{"text":"Stir in the tomato paste and cook for 1 minute to deepen the flavour."},{"text":"Pour in the coconut milk and fish stock, stirring to combine. Bring to a gentle simmer until small bubbles break the surface, then reduce the heat to medium-low."},{"text":"Carefully add the fish chunks to the pot, season with salt and pepper, and simmer gently for 12 to 15 minutes, until the fish is just cooked through and flakes easily. Do not stir vigorously; gently turn the fish once halfway through."},{"text":"Taste and adjust seasoning if needed. Serve hot, scattered with fresh coriander and lime wedges on the side."}],"id":"52320754-6ad1-4672-9de1-c4b8d8b56fa0"},{"notes":["This freezes brilliantly, make a double batch and freeze the cooled stir-fry in containers for a quick weeknight reheat. Thaw overnight in the fridge and warm in a pan over medium heat.","Use any frozen mixed veg (broccoli, carrot, capsicum, snap peas all work), or what's on special.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat 1 tbsp oil in a large wok or frying pan over high heat. Add the chicken strips and cook, stirring often, until cooked through (no pink inside), about 5 minutes. Transfer to a plate."},{"text":"Add the remaining oil to the pan. Add the frozen mixed vegetables and stir-fry for 2 minutes until starting to soften."},{"text":"Pour in the stir-fry sauce and honey, stirring to combine. Return the chicken to the pan and toss everything together until well coated and hot, about 1 minute."},{"text":"Divide rice or noodles between bowls, top with the stir-fry while the chicken is glossy and cooked through, and garnish with spring onion and sesame seeds if using."}],"id":"0dc5dad8-7f07-46ac-9f8a-f9b8dbfb809f"},{"notes":["Cime di rapa can be hard to find outside Italian delis, but gai lan (Chinese broccoli) works just as well, it's the same plant, just called by a different name.","Serve with a generous pour of your best olive oil and crusty bread to wipe the bowl."],"steps":[{"text":"Bring a large pot of salted water to the boil. Add the orecchiette and cook until al dente, about 12 minutes."},{"text":"While the pasta cooks, heat the olive oil in a large frying pan over medium heat. Add the garlic and chilli, and cook gently for 2–3 minutes, stirring often, until the garlic just turns golden, don't let it burn."},{"text":"Add the cime di rapa to the pan with a splash of water (about 100 ml) and a pinch of salt. Increase the heat to medium-high and cook, stirring occasionally, until the greens are tender, about 8 minutes."},{"text":"Reserve 200 ml of the pasta cooking water, then drain the pasta. Add it to the pan with the cime di rapa."},{"text":"Toss well, adding pasta water a little at a time, until everything is coated in a loose, silky sauce. The starch in the water helps emulsify the oil. Taste and adjust the salt and pepper."},{"text":"Serve hot, with a scatter of flaky salt if you like, and more chilli on the side for anyone who wants it."}],"id":"ae9fd6e1-e654-4535-950d-01d0f85250b5"},{"notes":["Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear. Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the oil in a large shallow pan over medium-high heat. Season the fish pieces with salt and pepper on both sides."},{"text":"Fry the fish for 2 minutes each side until lightly golden, then remove to a plate."},{"text":"In the same pan, sauté the garlic until fragrant, about 1 minute. Add the sliced onion and cook, stirring, until soft and translucent, about 4 minutes."},{"text":"Pour in the soy sauce and vinegar, stirring to combine. Bring to a gentle simmer until small bubbles appear and the sharp vinegar smell has softened."},{"text":"Return the fish to the pan, nestling the pieces among the onions. Simmer gently for 5–7 minutes, spooning the sauce over the fish occasionally, until the fish is cooked through and flakes easily when tested with a fork."},{"text":"Taste and adjust the salt if needed. Serve hot with the braising liquid and onions spooned over the fish, alongside steamed white rice."}],"id":"cbf409ab-0276-47e0-a275-92f596aea6a0"},{"notes":["Siraegi keeps well in the fridge for 3 days and can be served hot, warm or at room temperature.","If you can't find dried radish greens, look for them in Asian markets labelled as 'siraegi' or 'siraegi', they're worth seeking out."],"id":"23ab88a1-88bb-4b4c-80a9-ad5cf34f9979"},{"notes":["This works best on a gas burner where you can crank the heat. The wok needs to be hot enough that the curry paste caramelises rather than steams.","If you don't have Thai basil, regular basil works, or just serve it plain with rice.","Scale up easily: use 400g chicken for two plates, but keep cooking time about the same, high heat, 8–10 minutes total.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Heat your wok or heavy frying pan over high heat until it's smoking hot, about 2 minutes."},{"text":"Pour in the oil and swirl it around. It should shimmer immediately."},{"text":"Add the garlic and chillies. Stir for 15 seconds until fragrant."},{"text":"Add the chicken pieces, breaking them up with your spatula. Let them sit for 30 seconds without moving, you want them to catch colour."},{"text":"Stir and cook for 2 minutes until the chicken is mostly cooked through and the edges are starting to char."},{"text":"Add the curry paste, fish sauce and palm sugar. Toss everything together for another 2 minutes. You're looking for the paste to caramelise into the chicken and the whole thing to smell fierce."},{"text":"Taste and adjust the salt and heat if you need to. The chicken should be cooked through (75°C inside), with charred, sticky edges."},{"text":"Serve straight onto a plate with jasmine rice and fresh Thai basil if you have it."}],"id":"aec00c06-c1d1-412b-9594-10ec09e1b86d"},{"notes":["For a fully vegan dish, use soy sauce instead of fish sauce and check that your curry paste and coconut milk are vegan-certified.","You can prep all the vegetables ahead of time. Layer them in the pot just before cooking.","Leftovers keep well for 2 days in the fridge. Reheat gently on the stove with a splash of water."],"steps":[{"text":"Heat the oil in a clay pot (or heavy-bottomed pot) over medium heat. Add the curry paste and sliced garlic, stirring gently until fragrant, about 2 minutes."},{"text":"Pour in the coconut milk, vegetable stock, fish sauce and palm sugar. Stir well and let it come to a gentle simmer until bubbling lightly and the palm sugar has melted."},{"text":"Layer the noodles evenly over the curry sauce. Don't stir, just press them down gently so they're submerged."},{"text":"Layer the potato slices over the noodles, then add the mushrooms, capsicum and bok choy in separate layers on top. Pour any remaining sauce over everything."},{"text":"Cover the pot and simmer gently for 20 to 25 minutes, until the potatoes are tender and the noodles have absorbed the sauce. Peek at it after 15 minutes, it should smell deeply fragrant."},{"text":"Gently stir everything together just before serving. Taste and adjust the seasoning. Serve hot, topped with fresh Thai basil and coriander if you have them."}],"id":"6cb69a61-c448-49f7-bd17-539d4455d64a"},{"notes":["Saltfish needs to be soaked overnight to remove excess salt. If you're short on time, use 400 g fresh white fish fillet instead, add it to the stew in the last 5 minutes of cooking.","Green fig is unripe plantain, boiled until tender. Look for it in Caribbean or Latin markets, or swap for potato or sweet potato.","The stew tastes better the next day. Keep it in the fridge for up to 3 days and reheat gently on the stove."],"id":"f7072873-77df-431f-ae68-26f0de06fe46"},{"notes":["The batter can be made several hours ahead and chilled.","The apple compote keeps in the fridge for up to 3 days and can be gently reheated.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"bb908603-bef9-4730-88a7-a5454a5f9297"},{"notes":["The balance of tamarind to palm sugar is personal. Start with equal parts and adjust to taste, some prefer it more sour, others more rounded.","Make the vegetable stock a day ahead if you can; let it chill overnight so any sediment sinks to the bottom, and the broth will be clearer."],"steps":[{"text":"Bring the vegetable stock to a gentle simmer in a large pot. Stir in the tamarind paste and palm sugar until dissolved, about 2 minutes. Taste and adjust the balance of sour and sweet, it should brighten your tongue but not overwhelm it."},{"text":"Add the pumpkin slices and simmer for 5 minutes until they are just tender but still hold their shape."},{"text":"Add the mushrooms and tofu cubes. Simmer gently for 8 minutes, stirring occasionally, until the mushrooms are soft and the tofu has absorbed some of the broth's flavour."},{"text":"Add the tomato wedges and season with salt and black pepper. Simmer for 2 more minutes until the tomatoes are softened, the tomatoes should be warm but still hold their shape."},{"text":"Remove from heat and stir through most of the fresh dill and coriander, reserving some for serving. Taste once more and adjust the seasoning if needed."},{"text":"Ladle into bowls and garnish with the remaining herbs and red chilli slices if using. Serve at once, while the broth is still steaming."}],"id":"007e4b00-3d49-4aee-b221-6e18ebeecd0a"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;